package ochazuke

import (
	"fmt"
	"math"
	"strconv"
)

// The hue palette is generated by one rule, so no colour is hand-picked,
// and it is as large as keeps every pair clearly different. Candidates are
// every hue at paletteHueStep degrees in OKLCH at five lightness levels
// (light levels dark enough to read on the light surface, dark levels
// light enough for the dark one) and chroma paletteChroma, cut back where
// a hue leaves the sRGB gamut. Colours are chosen farthest-first: each next
// is the candidate whose nearest chosen colour is furthest away, until none
// is far enough. "Far enough" is OKLab distance, on both built-in
// surfaces: paletteMinDistance between any two (about five just-noticeable
// differences: two thin border lines or two titles are told apart at a
// glance), paletteMinFadedDistance between a colour as an unfocused panel
// draws it (faded HueFadePercent toward the surface) and any other colour
// at full strength, and paletteMinReserved from the error red and the
// needs-input amber, which a hue must not imitate. The first colours chosen
// are therefore the most different from each other. hue_test.go holds the
// bounds; a theme overrides any palette.N in themes.json.
const (
	paletteHueStep          = 3
	paletteChroma           = 0.18
	paletteMinDistance      = 0.10
	paletteMinFadedDistance = 0.06
	paletteMinReserved      = 0.06
)

var (
	paletteLightL = []float64{0.40, 0.46, 0.52, 0.58, 0.62}
	paletteDarkL  = []float64{0.66, 0.72, 0.78, 0.84, 0.88}
	// paletteReserved are the error red and the needs-input amber, light
	// side then dark side.
	paletteReserved = [2][]string{{"#AB3D36", "#9A6700"}, {"#E99B8D", "#E3B341"}}
	// The built-in surfaces the palette is chosen against.
	paletteSurface = [2]string{"#EEF3EF", "#172720"}
)

// paletteRow is one palette tone's light and dark colour.
type paletteRow struct{ light, dark string }

// paletteRows are the generated palette, palette.i being paletteRows[i].
var paletteRows = generatePalette()

// paletteCand is a candidate colour with its OKLab coordinates per side.
type paletteCand struct {
	row paletteRow
	lab [2][3]float64
}

func generatePalette() []paletteRow {
	surf := [2][3]float64{hexOKLab(paletteSurface[0]), hexOKLab(paletteSurface[1])}
	var res [2][][3]float64
	for side := range res {
		for _, h := range paletteReserved[side] {
			res[side] = append(res[side], hexOKLab(h))
		}
	}
	fade := func(c, s [3]float64) [3]float64 {
		p := float64(HueFadePercent) / 100
		return [3]float64{c[0] + (s[0]-c[0])*p, c[1] + (s[1]-c[1])*p, c[2] + (s[2]-c[2])*p}
	}
	var cands []paletteCand
	for h := 0; h < 360; h += paletteHueStep {
		for level := range paletteLightL {
			c := paletteCand{row: paletteRow{oklchHex(paletteLightL[level], paletteChroma, float64(h)), oklchHex(paletteDarkL[level], paletteChroma, float64(h))}}
			c.lab = [2][3]float64{hexOKLab(c.row.light), hexOKLab(c.row.dark)}
			keep := true
			for side := range res {
				for _, r := range res[side] {
					keep = keep && labDistance(c.lab[side], r) >= paletteMinReserved
				}
			}
			if keep {
				cands = append(cands, c)
			}
		}
	}
	// score is how far c is from s in units of the least allowed: 1 or more
	// is far enough.
	score := func(c, s paletteCand) float64 {
		m := math.MaxFloat64
		for side := range surf {
			m = math.Min(m, labDistance(c.lab[side], s.lab[side])/paletteMinDistance)
			m = math.Min(m, labDistance(fade(c.lab[side], surf[side]), s.lab[side])/paletteMinFadedDistance)
			m = math.Min(m, labDistance(fade(s.lab[side], surf[side]), c.lab[side])/paletteMinFadedDistance)
		}
		return m
	}
	chosen := []paletteCand{cands[0]}
	for {
		best, bestScore := -1, -1.0
		for i, c := range cands {
			m := math.MaxFloat64
			for _, s := range chosen {
				m = math.Min(m, score(c, s))
			}
			if m > bestScore+1e-9 {
				best, bestScore = i, m
			}
		}
		if bestScore < 1 {
			break
		}
		chosen = append(chosen, cands[best])
	}
	rows := make([]paletteRow, len(chosen))
	for i, c := range chosen {
		rows[i] = c.row
	}
	return rows
}

// hexOKLab is the OKLab coordinates of an sRGB hex colour.
func hexOKLab(h string) [3]float64 {
	var v [3]float64
	for i := range v {
		n, _ := strconv.ParseInt(h[1+2*i:3+2*i], 16, 32)
		x := float64(n) / 255
		if x <= 0.04045 {
			v[i] = x / 12.92
		} else {
			v[i] = math.Pow((x+0.055)/1.055, 2.4)
		}
	}
	l := math.Cbrt(0.4122214708*v[0] + 0.5363325363*v[1] + 0.0514459929*v[2])
	m := math.Cbrt(0.2119034982*v[0] + 0.6806995451*v[1] + 0.1073969566*v[2])
	s := math.Cbrt(0.0883024619*v[0] + 0.2817188376*v[1] + 0.6299787005*v[2])
	return [3]float64{0.2104542553*l + 0.7936177850*m - 0.0040720468*s, 1.9779984951*l - 2.4285922050*m + 0.4505937099*s, 0.0259040371*l + 0.7827717662*m - 0.8086757660*s}
}

func labDistance(a, b [3]float64) float64 {
	return math.Sqrt((a[0]-b[0])*(a[0]-b[0]) + (a[1]-b[1])*(a[1]-b[1]) + (a[2]-b[2])*(a[2]-b[2]))
}

// withPaletteTones adds palette.N to tones.
func withPaletteTones(tones map[string]ToneStyle) map[string]ToneStyle {
	for i, r := range paletteRows {
		tones["palette."+strconv.Itoa(i)] = ToneStyle{Fg: SchemeColor{r.light, r.dark}}
	}
	return tones
}

// oklchLinear is the linear sRGB of an OKLCH colour.
func oklchLinear(l, c, h float64) (r, g, b float64) {
	a, bb := c*math.Cos(h*math.Pi/180), c*math.Sin(h*math.Pi/180)
	l_, m_, s_ := l+0.3963377774*a+0.2158037573*bb, l-0.1055613458*a-0.0638541728*bb, l-0.0894841775*a-1.2914855480*bb
	l3, m3, s3 := l_*l_*l_, m_*m_*m_, s_*s_*s_
	return 4.0767416621*l3 - 3.3077115913*m3 + 0.2309699292*s3,
		-1.2684380046*l3 + 2.6097574011*m3 - 0.3413193965*s3,
		-0.0041960863*l3 - 0.7034186147*m3 + 1.7076147010*s3
}

// oklchHex is the sRGB hex of an OKLCH colour, its chroma cut back until it
// fits the gamut.
func oklchHex(l, c, h float64) string {
	inGamut := func(c float64) bool {
		r, g, b := oklchLinear(l, c, h)
		return r >= -1e-4 && r <= 1+1e-4 && g >= -1e-4 && g <= 1+1e-4 && b >= -1e-4 && b <= 1+1e-4
	}
	if !inGamut(c) {
		lo, hi := 0.0, c
		for range 30 {
			if mid := (lo + hi) / 2; inGamut(mid) {
				lo = mid
			} else {
				hi = mid
			}
		}
		c = lo
	}
	r, g, b := oklchLinear(l, c, h)
	enc := func(x float64) int {
		x = math.Min(1, math.Max(0, x))
		if x <= 0.0031308 {
			x *= 12.92
		} else {
			x = 1.055*math.Pow(x, 1/2.4) - 0.055
		}
		return int(math.Round(x * 255))
	}
	return fmt.Sprintf("#%02X%02X%02X", enc(r), enc(g), enc(b))
}
